export const CatalogWeapons = CatalogEquipment.filter(e => e.category === 0);

export class WeaponsCatalogWeb {
  constructor(engine) {
    this.engine = engine;
    this.open = false;
    this.selectedJob = 1; // 1: Guerreiro, 2: Atirador, 3: Ladino
    this.selectedCategory = 0; // 0: Armas, 1: Armaduras
    this.page = 0;
    this.discovered = new Set(); // formato: "id:rarity"
  }

  record(id, rarity) {
    this.discovered.add(`${id}:${rarity}`);
  }

  isRecorded(id, rarity) {
    return this.discovered.has(`${id}:${rarity}`);
  }

  getItemsForJob(job, category = this.selectedCategory) {
    return CatalogEquipment.filter(w => w.job === job && w.category === category);
  }

  getWeaponsForJob(job) {
    return this.getItemsForJob(job, 0);
  }

  getCompletionPercentage(job) {
    const list = CatalogEquipment.filter(w => w.job === job);
    if (!list.length) return 100;
    let found = 0;
    for (const w of list) {
      for (let r = 0; r < 5; ++r) {
        if (this.isRecorded(w.id, r)) found++;
      }
    }
    return Math.min(100, (found / (list.length * 5)) * 100);
  }

  scanInventory() {
    if (!this.engine?.exports) return;
    const g = this.engine.exports.get("Game");
    if (!g) return;

    for (let b = 0; b < 4; ++b) {
      const count = this.engine.get16(g + 0x433c + b * 0x92);
      if (count > 24) continue;
      for (let i = 0; i < count; ++i) {
        const record = g + 0x433e + b * 0x92 + 6 * i;
        if (!this.engine.get16(record + 4) || this.engine.get16(record) !== 0) continue;
        const pool = this.engine.get16(record + 2);
        if (pool >= 200) continue;

        const header = this.engine.get16(g + 0x2ed6 + 20 * pool);
        const itemType = (header >> 5) & 7; // 0 = Arma, 1 = Armadura (peitoral)
        if (itemType !== 0 && itemType !== 1) continue;

        const rank = (header >> 8) & 7; // Raridade 0..4
        if (rank > 4) continue;

        const minLv = header & 0x1f;
        const targetCategory = itemType; // 0 ou 1
        for (const eq of CatalogEquipment) {
          if (eq.category === targetCategory && eq.level <= minLv) {
            this.record(eq.id, rank);
          }
        }
      }
    }
  }

  toggle() {
    this.open = !this.open;
    if (this.open) {
      this.scanInventory();
    }
    return this.open;
  }

  toggleCategory() {
    this.selectedCategory = this.selectedCategory === 0 ? 1 : 0;
    this.page = 0;
  }

  handleKey(key, down) {
    if (!this.open) return false;
    if (!down) return true;

    if (key === 27 || key === 10 || key === 'w' || key === 'W' || key === 'F4') { // ESC / Voltar
      this.open = false;
      return true;
    }
    if (key === 't' || key === 'T') {
      this.toggleCategory();
      return true;
    }
    if (key === 3 || key === 5) { // Anterior
      if (this.page > 0) this.page--;
      return true;
    }
    if (key === 9 || key === 7) { // Próximo
      const list = this.getItemsForJob(this.selectedJob, this.selectedCategory);
      const totalPages = Math.ceil(list.length / 4);
      if (this.page + 1 < totalPages) this.page++;
      return true;
    }
    if (key === 1 || key === '1') { this.selectedJob = 1; this.page = 0; return true; }
    if (key === 2 || key === '2') { this.selectedJob = 2; this.page = 0; return true; }
    if (key === 3 || key === '3') { this.selectedJob = 3; this.page = 0; return true; }
    if (key === 9 || key === '\t') { // TAB
      this.selectedJob = (this.selectedJob % 3) + 1;
      this.page = 0;
      return true;
    }
    return true;
  }

  handleTouch(x,y,type) {
    if(!this.open)return false;
    if(type!==0)return true;
    const l=this.layout();x=(x-l.x)/l.scale;y=(y-l.y)/l.scale;
    if(x>=320&&x<356&&y>=4&&y<24){this.open=false;return true;}
    if(y>=34&&y<56){
      if(x>=270&&x<350)this.toggleCategory();
      else for(let i=0;i<3;i++)if(x>=10+i*85&&x<90+i*85){this.selectedJob=i+1;this.page=0;}
    }
    if(y>=184&&y<207){if(x>=10&&x<100&&this.page>0)this.page--;if(x>=260&&x<350&&this.page+1<Math.ceil(this.getItemsForJob(this.selectedJob).length/4))this.page++;}
    return true;
  }
  layout() {
    const width=this.engine.width||400,height=this.engine.height||240;
    const scale=Math.min(width/400,height/240);
    return {scale,x:(width-360*scale)/2,y:(height-220*scale)/2};
  }

  paint(pixels) {
    const ui=this.engine.originalUi;
    if(!this.open||!ui||!pixels)return;
    const {scale:s,x,y}=this.layout();
    const panel=(a,b,w,h)=>ui.panel(pixels,{x:x+a*s,y:y+b*s,w:w*s,h:h*s});
    const text=(a,b,value,color=0xffff,w=340-a)=>ui.text(pixels,x+a*s,y+b*s,value,color,w*s,s);
    panel(0,0,360,220);
    text(324,7,'SAIR',0xffc0,30);
    text(10,7,'CATALOGO',0xffc0,220);
    text(120,7,Math.floor(this.getCompletionPercentage(this.selectedJob))+'% completo',0xffff,195);
    ['Guerreiro','Atirador','Ladino'].forEach((label,i)=>{panel(10+i*85,34,80,22);text(14+i*85,39,label,this.selectedJob===i+1?0xffc0:0xffff,74);});
    panel(270,34,80,22);text(274,39,this.selectedCategory?'Armaduras':'Armas',0xffc0,74);
    const list=this.getItemsForJob(this.selectedJob);
    list.slice(this.page*4,this.page*4+4).forEach((item,i)=>{
      const row=62+i*29;panel(10,row,340,28);
      text(15,row+3,item.name,0xffff,230);text(260,row+3,'Nv '+item.level,0xffc0,85);
      text(15,row+15,item.type,0x8c51,180);
      text(200,row+15,'R: '+[0,1,2,3,4].map(r=>this.isRecorded(item.id,r)?r+1:'-').join(' '),0xffc0,145);
    });
    panel(10,184,90,22);text(15,189,'ANTERIOR',0xffff,80);
    text(150,189,(this.page+1)+' / '+Math.ceil(list.length/4),0xffff,85);
    panel(260,184,90,22);text(266,189,'PROXIMO',0xffff,80);
    text(10,207,'1/2/3 classe  T categoria  Setas pagina',0x8c51,340);
  }
}
